import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"My Wallet – Account Balance","description":"","frontmatter":{"title":"My Wallet – Account Balance"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/my-wallet-account-balance.md","filePath":"operations-knowledge-base/presales-support/my-wallet-account-balance.md","lastUpdated":1794292919000}'),r={name:"operations-knowledge-base/presales-support/my-wallet-account-balance.md"};function i(l,e,c,s,u,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h2 id="_1-feature-overview" tabindex="-1">1. Feature Overview <a class="header-anchor" href="#_1-feature-overview" aria-label="Permalink to &quot;1. Feature Overview&quot;">​</a></h2><p>The platform’s billing module supports account top-up and balance change record inquiries, helping users clearly track account fund movements and balance status and complete fund-related operations more conveniently.</p><h2 id="_2-account-balance-and-recharge" tabindex="-1">2. Account Balance and Recharge <a class="header-anchor" href="#_2-account-balance-and-recharge" aria-label="Permalink to &quot;2. Account Balance and Recharge&quot;">​</a></h2><h3 id="_1-access-path" tabindex="-1">(1) Access Path <a class="header-anchor" href="#_1-access-path" aria-label="Permalink to &quot;(1) Access Path&quot;">​</a></h3><p>Navigate to Customer Center → Billing → My Wallet to enter the Account Balance page.</p><h3 id="_2-feature-description" tabindex="-1">(2) Feature Description <a class="header-anchor" href="#_2-feature-description" aria-label="Permalink to &quot;(2) Feature Description&quot;">​</a></h3><p>At the top of the page, the current account balance is displayed.</p><p>On the right side, there is an “Add Funds” button. Clicking this button will take you to the account top-up page to complete the deposit process.</p><h2 id="_3-account-recharge" tabindex="-1">3. Account Recharge <a class="header-anchor" href="#_3-account-recharge" aria-label="Permalink to &quot;3. Account Recharge&quot;">​</a></h2><h3 id="feature-description" tabindex="-1">Feature Description <a class="header-anchor" href="#feature-description" aria-label="Permalink to &quot;Feature Description&quot;">​</a></h3><h4 id="recharge-rules" tabindex="-1">Recharge Rules <a class="header-anchor" href="#recharge-rules" aria-label="Permalink to &quot;Recharge Rules&quot;">​</a></h4><ul><li>Minimum top-up amount: $1.00 USD</li><li>Maximum top-up amount: $20,000.00 USD</li><li>Maximum account balance limit: $100,000.00 USD</li></ul><h4 id="operation-process" tabindex="-1">Operation Process <a class="header-anchor" href="#operation-process" aria-label="Permalink to &quot;Operation Process&quot;">​</a></h4><ul><li>Enter a valid amount in the “Recharge Amount” input field.</li><li>Select a payment method from the “Payment Method” dropdown menu, such as BitPay, PayPal, or Alipay - 5.</li><li>Click the “Add Funds” button to complete the top-up.</li></ul><h4 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important Notes&quot;">​</a></h4><ul><li>Account balance withdrawals are not supported.</li><li>Please confirm the top-up amount and payment method carefully before completing the transaction to avoid errors.</li></ul><h2 id="_4-balance-change-details" tabindex="-1">4. Balance Change Details <a class="header-anchor" href="#_4-balance-change-details" aria-label="Permalink to &quot;4. Balance Change Details&quot;">​</a></h2><h2 id="feature-description-1" tabindex="-1">Feature Description <a class="header-anchor" href="#feature-description-1" aria-label="Permalink to &quot;Feature Description&quot;">​</a></h2><h3 id="query-and-filtering" tabindex="-1">Query and Filtering <a class="header-anchor" href="#query-and-filtering" aria-label="Permalink to &quot;Query and Filtering&quot;">​</a></h3><p>Users can filter transaction records by selecting Start Date and End Date, with quick options such as:</p><ul><li>Last 7 Days</li><li>Last 30 Days</li></ul><p>Users can also use the “Filter Status” dropdown menu to select:</p><ul><li>All</li><li>Income (Funds Added)</li><li>Expense (Funds Spent)</li></ul><p>After selecting the desired options, click “Search” to view the corresponding transaction records.</p><h3 id="transaction-details" tabindex="-1">Transaction Details <a class="header-anchor" href="#transaction-details" aria-label="Permalink to &quot;Transaction Details&quot;">​</a></h3><p>The transaction list includes the following information:</p><p><strong>Transaction Date</strong> The exact date when the balance change occurred.</p><p><strong>Description</strong> The reason for the balance change (e.g., “Credit Applied to Invoice #XXX” indicates a payment applied to an invoice, while “Add Funds Invoice #XXX” indicates an account top-up).</p><p><strong>Amount</strong></p><ul><li>Positive values represent funds added (e.g., top-ups or refunds).</li><li>Negative values represent funds spent (e.g., invoice payments).</li></ul><p><strong>Credit</strong> The real-time account balance after each transaction is completed.</p><h3 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h3><p>The bottom of the page supports pagination for viewing more transaction records.</p><p>Users can switch pages using the “Previous” and “Next” buttons.</p>',34)])])}const m=a(r,[["render",i]]);export{p as __pageData,m as default};
